// Repro for bucket B1 (data_byte_fail): the eight data bits must be sent
// least significant bit first. Only the data byte is checked; parity and
// frame length are deliberately not checked here.
`timescale 1ns / 1ps
module tb_uart_data_order;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    integer        checks;
    integer        failed;
    reg            reported;
    reg [8*64-1:0] nonce;
    reg [7:0]      got;
    reg [7:0]      vec [0:3];
    integer        k;

    task report;
        begin
            if (!reported) begin
                reported = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d result=%0s",
                         nonce, checks, failed, (failed != 0) ? "FAIL" : "PASS");
                $finish;
            end
        end
    endtask

    // Send one byte and capture the eight data bits, LSB first, mid-bit.
    task capture_data(input [7:0] b);
        integer i;
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(negedge tx);                 // start bit begins
            @(negedge clk);
            start = 1'b0;
            repeat (CPB / 2) @(posedge clk);
            #1;                            // middle of the start bit
            for (i = 0; i < 8; i = i + 1) begin
                repeat (CPB) @(posedge clk);
                #1;                        // middle of data bit i
                got[i] = tx;
            end
            wait (busy == 1'b0);
            repeat (3) @(posedge clk);
        end
    endtask

    initial begin
        checks   = 0;
        failed   = 0;
        reported = 1'b0;
        if (!$value$plusargs("nonce=%s", nonce)) nonce = "none";
        vec[0] = 8'h01;
        vec[1] = 8'hD2;
        vec[2] = 8'h80;
        vec[3] = 8'h0F;
        repeat (4) @(posedge clk);
        @(negedge clk);
        rst = 1'b0;
        repeat (4) @(posedge clk);
        for (k = 0; k < 4; k = k + 1) begin
            capture_data(vec[k]);
            checks = checks + 1;
            if (got !== vec[k]) begin
                failed = failed + 1;
                $display("CHECK data_order FAILED: sent 8'h%02h, received LSB-first 8'h%02h", vec[k], got);
            end else begin
                $display("CHECK data_order ok: 8'h%02h", vec[k]);
            end
        end
        report;
    end

    initial begin
        #100000;
        $display("CHECK watchdog FAILED: frame did not complete in time");
        checks = checks + 1;
        failed = failed + 1;
        report;
    end
endmodule
=== END FILE ===
