// Repro for bucket B2 (parity_bit_fail): the parity bit must be even parity,
// i.e. equal to ^data. Only the parity bit is checked; data order and frame
// length are deliberately not checked here.
`timescale 1ns / 1ps
module tb_uart_parity;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    integer        checks;
    integer        failed;
    reg            reported;
    reg [8*64-1:0] nonce;
    reg            got_par;
    reg [7:0]      vec [0:4];
    integer        k;

    task report;
        begin
            if (!reported) begin
                reported = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d result=%0s",
                         nonce, checks, failed, (failed != 0) ? "FAIL" : "PASS");
                $finish;
            end
        end
    endtask

    // Send one byte and capture the parity bit (the bit after the 8 data bits), mid-bit.
    task capture_parity(input [7:0] b);
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(negedge tx);                 // start bit begins
            @(negedge clk);
            start = 1'b0;
            repeat (CPB / 2) @(posedge clk);
            #1;                            // middle of the start bit
            repeat (9 * CPB) @(posedge clk);
            #1;                            // middle of the parity bit
            got_par = tx;
            wait (busy == 1'b0);
            repeat (3) @(posedge clk);
        end
    endtask

    initial begin
        checks   = 0;
        failed   = 0;
        reported = 1'b0;
        if (!$value$plusargs("nonce=%s", nonce)) nonce = "none";
        vec[0] = 8'h00;
        vec[1] = 8'h01;
        vec[2] = 8'hFF;
        vec[3] = 8'hD2;
        vec[4] = 8'h07;
        repeat (4) @(posedge clk);
        @(negedge clk);
        rst = 1'b0;
        repeat (4) @(posedge clk);
        for (k = 0; k < 5; k = k + 1) begin
            capture_parity(vec[k]);
            checks = checks + 1;
            if (got_par !== (^vec[k])) begin
                failed = failed + 1;
                $display("CHECK even_parity FAILED: data 8'h%02h, parity bit %b, expected %b",
                         vec[k], got_par, ^vec[k]);
            end else begin
                $display("CHECK even_parity ok: data 8'h%02h", vec[k]);
            end
        end
        report;
    end

    initial begin
        #100000;
        $display("CHECK watchdog FAILED: frame did not complete in time");
        checks = checks + 1;
        failed = failed + 1;
        report;
    end
endmodule
