// Repro for bucket B3 (frame_period_fail): a frame (start, 8 data, parity,
// stop) must last 11 bit periods, so busy stays high for 11*CLKS_PER_BIT
// cycles. Data and parity values are deliberately not checked here.
`timescale 1ns / 1ps
module tb_uart_frame_period;
    localparam integer CPB = 4;
    localparam integer EXPECTED_CYCLES = 11 * CPB;
    localparam integer NONCE_CHARS = 256;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    integer                   checks;
    integer                   failed;
    reg                       reported;
    reg [8*NONCE_CHARS-1:0]   nonce;
    integer                   cycles;
    reg [7:0]                 vec [0:1];
    integer                   k;

    task read_nonce;
        begin
            nonce = {8*NONCE_CHARS{1'b0}};
            if (!$value$plusargs("nonce=%s", nonce))
            if (!$value$plusargs("NONCE=%s", nonce))
            if (!$value$plusargs("verdict_nonce=%s", nonce))
            if (!$value$plusargs("VERDICT_NONCE=%s", nonce))
                nonce = "none";
        end
    endtask

    task print_nonce;
        integer j;
        reg [7:0] c;
        begin
            for (j = NONCE_CHARS - 1; j >= 0; j = j - 1) begin
                c = nonce[j*8 +: 8];
                if (c != 8'd0) $write("%c", c);
            end
        end
    endtask

    task report;
        begin
            if (!reported) begin
                reported = 1'b1;
                $write("VERDICT nonce=");
                print_nonce;
                $display(" checks=%0d failed=%0d result=%s",
                         checks, failed, (failed != 0) ? "FAIL" : "PASS");
                $finish;
            end
        end
    endtask

    // Start one frame and count the clock cycles busy stays high.
    task measure_frame(input [7:0] b);
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(posedge clk);                // start accepted on this edge
            #1;
            start  = 1'b0;
            cycles = 0;
            while (busy === 1'b1 && cycles < 1000) begin
                @(posedge clk);
                #1;
                cycles = cycles + 1;
            end
            repeat (3) @(posedge clk);
        end
    endtask

    initial begin
        checks   = 0;
        failed   = 0;
        reported = 1'b0;
        read_nonce;
        vec[0] = 8'h55;
        vec[1] = 8'hC3;
        repeat (4) @(posedge clk);
        @(negedge clk);
        rst = 1'b0;
        repeat (4) @(posedge clk);
        for (k = 0; k < 2; k = k + 1) begin
            measure_frame(vec[k]);
            checks = checks + 1;
            if (cycles != EXPECTED_CYCLES) begin
                failed = failed + 1;
                $display("CHECK frame_period FAILED: busy high for %0d cycles, expected %0d",
                         cycles, EXPECTED_CYCLES);
            end else begin
                $display("CHECK frame_period ok: %0d cycles", cycles);
            end
        end
        report;
    end

    initial begin
        #100000;
        $display("CHECK watchdog FAILED: frame did not complete in time");
        checks = checks + 1;
        failed = failed + 1;
        report;
    end
endmodule
